// CloudtainerML rev0023: provenance-grounded gating + adaptive recovery toy.
// Synthetic C++17 probe for curation pipelines: source-faithfulness gate, reward gate,
// and rejected-sample recovery. Not a paper reproduction.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <random>
#include <string>
#include <vector>
struct Sample{double reward, provenance, halluc, injection, difficulty;};
struct Row{std::string regime,method; int n=0; double yield=0,valid=0,injrec=0,recovered=0,quality=0,utility=0;};
static std::string esc(const std::string&s){std::string o; for(char c:s){if(c=='"')o+="\\\""; else if(c=='\\')o+="\\\\"; else o+=c;} return o;}
static double rnd(std::mt19937_64&r,double a=0,double b=1){return std::uniform_real_distribution<double>(a,b)(r);} 
static Sample sample(std::mt19937_64&rng,const std::string&reg){Sample s; s.difficulty=rnd(rng); s.reward=rnd(rng); s.provenance=rnd(rng); s.halluc=rnd(rng)*0.45; s.injection=rnd(rng)<0.08; if(reg=="reward_hacking"){s.reward=0.65+rnd(rng)*0.35; if(rnd(rng)<0.38){s.provenance*=0.35; s.halluc=0.55+rnd(rng)*0.45;}} if(reg=="source_injection"){if(rnd(rng)<0.22){s.injection=true; s.reward=0.55+rnd(rng)*0.35; s.provenance=0.30+rnd(rng)*0.35;}} if(reg=="weak_generator"){s.reward*=0.75; s.provenance*=0.8; s.halluc+=0.25*rnd(rng);} if(reg=="strong_generator"){s.reward=0.35+0.65*s.reward; s.provenance=0.45+0.55*s.provenance; s.halluc*=0.45;} return s;}
static bool valid(const Sample&s){return s.provenance>0.58 && s.halluc<0.32 && !s.injection && s.reward>0.42;}
static Sample recover(std::mt19937_64&rng, Sample s, const std::string&method){ if(method=="naive_resample"){return sample(rng,"strong_generator");} // targeted fix based on diagnosed failure
    if(s.provenance<=0.58) s.provenance=std::min(1.0,s.provenance+0.25+0.25*rnd(rng)); if(s.halluc>=0.32) s.halluc=std::max(0.0,s.halluc-(0.20+0.20*rnd(rng))); if(s.injection && rnd(rng)<0.68) s.injection=false; if(s.reward<=0.42) s.reward=std::min(1.0,s.reward+0.18+0.12*rnd(rng)); return s; }
static void eval(const std::string&reg,const std::string&m,int seed,double&yield,double&validr,double&injrec,double&recr,double&qual,double&util){std::mt19937_64 rng(seed); int N=260; int acc=0, val=0, inj=0, inj_caught=0, rec=0; double q=0; for(int i=0;i<N;++i){Sample s=sample(rng,reg); if(s.injection) inj++; bool keep=false; if(m=="reward_only_gate") keep=s.reward>0.58; else if(m=="provenance_only_gate") keep=s.provenance>0.62 && s.halluc<0.48; else if(m=="dual_gate") keep=s.reward>0.50 && s.provenance>0.58 && s.halluc<0.38; else if(m=="dual_gate_adaptive_recovery") keep=s.reward>0.50 && s.provenance>0.58 && s.halluc<0.38; else if(m=="naive_resample") keep=s.reward>0.50 && s.provenance>0.55 && s.halluc<0.42; else keep=true; if(!keep && s.injection) inj_caught++; if(!keep && (m=="dual_gate_adaptive_recovery"||m=="naive_resample")){Sample t=recover(rng,s,m); if(valid(t) && t.reward>0.45){keep=true; s=t; rec++;}} if(keep){acc++; if(valid(s))val++; q+=0.55*s.reward+0.45*s.provenance-0.65*s.halluc-(s.injection?1.0:0.0);} }
 yield=(double)acc/N; validr=acc?double(val)/acc:0; injrec=inj?double(inj_caught)/inj:1.0; recr=(double)rec/N; qual=acc?q/acc:0; util=1.15*yield+1.7*validr+1.25*injrec+0.85*recr+0.55*qual-(m=="dual_gate_adaptive_recovery"?0.18:m=="naive_resample"?0.28:0.0);}
static void add(Row&r,double y,double v,double i,double rc,double q,double u){r.n++; r.yield+=y; r.valid+=v; r.injrec+=i; r.recovered+=rc; r.quality+=q; r.utility+=u;}
int main(int argc,char**argv){std::string out="artifacts/probe-results/REV0023_PROVENANCE_RECOVERY_GATE_SMOKE.json"; if(argc>1)out=argv[1]; auto t0=std::chrono::high_resolution_clock::now(); std::vector<std::string> regs={"reward_hacking","source_injection","weak_generator","strong_generator","mixed"}; std::vector<std::string> ms={"reward_only_gate","provenance_only_gate","dual_gate","dual_gate_adaptive_recovery","naive_resample"}; std::map<std::string,Row> rows; std::map<std::string,int>wins; for(auto&reg:regs) for(int seed=0;seed<120;++seed){double best=-1e9; std::string bw; for(auto&m:ms){double y,v,i,rc,q,u; eval(reg,m,123+seed*43+reg.size()*11,y,v,i,rc,q,u); std::string key=reg+"|"+m; if(!rows.count(key)){rows[key].regime=reg; rows[key].method=m;} add(rows[key],y,v,i,rc,q,u); if(u>best){best=u; bw=m;}} wins[bw]++;}
 double sec=std::chrono::duration<double>(std::chrono::high_resolution_clock::now()-t0).count(); std::ofstream f(out); f<<std::fixed<<std::setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0023\",\n  \"probe\": \"provenance_recovery_gate\",\n  \"language\": \"c++17\",\n  \"is_paper_reproduction\": false,\n  \"taxonomy\": [\"data-curation\", \"provenance\", \"recovery\", \"memory-safety\"],\n"; f<<"  \"summary\": {\"row_count\": "<<rows.size()<<", \"seconds\": "<<sec<<", \"primary_metric\": {\"name\": \"mean_utility\", \"direction\": \"higher_is_better\", \"winner_field\": \"winner_counts\"}, \"tail_metrics\": {\"has_catastrophic_proxy\": true, \"fields\": [\"mean_injection_recall\", \"mean_valid_accept_rate\"]}, \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}, \"interpretation\": \"Provenance and reward gates catch disjoint failure populations; adaptive recovery tests whether rejected samples can be repaired instead of discarded.\"},\n  \"rows\": [\n"; int c=0; for(auto&kv:rows){auto&r=kv.second; double n=std::max(1,r.n); if(c++)f<<",\n"; f<<"    {\"regime\": \""<<esc(r.regime)<<"\", \"method\": \""<<esc(r.method)<<"\", \"mean_yield\": "<<r.yield/n<<", \"mean_valid_accept_rate\": "<<r.valid/n<<", \"mean_injection_recall\": "<<r.injrec/n<<", \"mean_recovery_rate\": "<<r.recovered/n<<", \"mean_quality\": "<<r.quality/n<<", \"mean_utility\": "<<r.utility/n<<"}";} f<<"\n  ]\n}\n"; std::cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n"; return 0;}
